custom_css:
/* <小手账> 作者by点心 Discord@老实人豁出去了 禁止二传二售 */

/* 修改位置标识：▶...◀ 若您为PC端/平板/窄屏小手机请直达末尾 修改响应式媒体查询布局 */ 

/* ===== 全局样式 ===== */

/* 字体 */
@import url("https://fontsapi.zeoseven.com/882/main/result.css");

body {
    font-family: "Monu Hani";
    font-weight: normal;
}

:root {
    --mycolor:rgb(177, 136, 156);
    --myshadow:147, 113, 136;
    --mydrawer:rgb(250, 243, 247);
    --mybutton:rgb(249, 240, 244);
    --myblack:rgb(34, 34, 34);
    --myhit:rgb(222, 185, 204);
    --myred:rgb(226, 148, 186);
    --mytextarea:rgb(235, 221, 229);
    --mylight:rgb(237, 216, 229);
    --myshadow2:rgb(243, 231, 237);
    --mygrey:rgb(140, 140, 140);
    --fontScale:0.98;
    --mypcvw:724px;
    --mypcmesvw:712px;

}

/* 滚动条 */
html, body {
    overflow-x: hidden !important;
}

#chat {
    max-width: 100vw !important;
    overflow-y: auto;
}

* {
    text-shadow: none !important;
    -webkit-tap-highlight-color: transparent !important;

    scrollbar-width: thin;
    scrollbar-color: var(--myhit) transparent;
}
::-webkit-scrollbar {
    width: 3px !important;
    height: 3px !important;
}
::-webkit-scrollbar-thumb {
    background: var(--myhit) !important;
    border-radius: 3px !important;
}
::-webkit-scrollbar-track {
    background: transparent !important;
}

/* ===== 全局样式结束 ===== */

/* 消息容器准备 */
#chat,
body.bubblechat .mes[is_user="true"] {
    background-color: transparent !important;
    border: none !important;
}

#chat {
    position: relative;
    max-height: calc(100vh - calc(var(--topBarBlockSize) )) !important;
    bottom: 0px;
    padding-bottom: 128px;  /* ▶最后一条消息与底栏的距离◀ */
}

/* 去除名字最小高度占位 */
.mes_block .ch_name {
    min-height: 0;
}

.slide {
    animation: none !important;
}

/* ===== 气泡 ===== */
body.bubblechat .mes {
    margin-bottom: 28px;  /* ▶气泡之间的距离改这里◀ */
}

.mes {
    --mespadding:6px;  /* ▶气泡宽窄改这里 越大越窄◀ */
    --mestextpadding:16px;  /* ▶正文 左右 间距改这里◀ */

    position: relative;
    isolation: isolate;

    max-width: 425px;
    border: none !important;
    background-color: transparent !important;
    padding: 150px var(--mespadding) 80px !important;  /* 留出top bottom空间 */
    margin-top: 60px;
    margin-left: auto;
    margin-right: auto;

    overflow: visible;
    box-shadow: none !important;
    filter: drop-shadow(1px 2px 3px rgba(var(--myshadow), 0.5));  /* 最外圈阴影浓度 */
    transform: translateZ(0); 
    will-change: filter;
}

.mes::before {
    content: "";
    position: absolute;
    top: 0px;
    left: var(--mespadding);
    width: calc(100% - var(--mespadding) * 2);
    height: 151px;  /* 顶部图片的高度 可实际效果微调 留出mes里top空间 */
    background:url('https://i.postimg.cc/X7q8Pb7x/firsttop.png') no-repeat top center;
    background-size:100% 100%;
    pointer-events: none;
}

.mes::after {
    content: "";
    position: absolute;
    bottom: 0px;
    left: var(--mespadding);
    width: calc(100% - var(--mespadding) * 2);
    height: 88px;
    background: 
        url('https://i.postimg.cc/9MZTQ3Gg/firstdirection2.png') no-repeat bottom 4px left 2px,
        url('https://i.postimg.cc/WzW749Sk/firstbtm.png') no-repeat bottom center;
    background-size: 100% 82px, 100% 81px;
    pointer-events: none;
    z-index: 1;
}

.mes_block {
    position: relative;
    width: 100%;
    padding-left: 0px !important;
    margin-left: 0px !important;
    background: url('https://i.postimg.cc/pLnB2JjG/firstmid.png') repeat-y;
    background-size: 100% auto;
    background-position: top center;
    border: none !important;
    overflow: visible;
}

.mes_block::before  {
    content: '';
    position: absolute;
    top: -188px;
    right: -2px;
    width: 100%;
    height: 186px;  /* 顶部装饰高度 可实际效果微调 */
    background: url('https://i.postimg.cc/NjKJ8tBz/firstdirection1.png') no-repeat top center;
    background-size:100% 100%;
    pointer-events: none;
    z-index: 1;
}

/* 名字 */
#chat .name_text {
    display: block;
    text-align: center;
    position: absolute !important;
    top: -76px;  /* ▶名字上下改这里◀ */
    left: 226px;  /* ▶名字左右改这里◀ */
    color: var(--mycolor);
    font-size: 1.4em;  /* ▶名字大小改这里◀ */
    width: 120px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    z-index: 10;
}

/* 日期 */
#chat .timestamp {
    position: absolute !important;
    top: -170px;  /* ▶日期上下改这里◀ */
    left: 242px;  /* ▶日期左右改这里◀ */
    opacity: 0.4;
    transform: rotate(6deg);
    z-index: 10;
}

/* 模型图标(?) */
.mes_block .icon-svg {
    position: absolute;
    top: -64px;  /* ▶模型图标上下改这里◀ */
    left: 350px;  /* ▶模型图标左右改这里◀ */
    opacity: 0.3;
    z-index: 10;
}

/* 铅笔、更多按钮 */
#chat .mes_button, 
#chat .extraMesButtons>div {
    color: var(--mycolor);
    filter: none !important;
    transition: none !important;
}
#chat .mes_buttons {
    position: absolute !important;
    top: -39px;  /* ▶铅笔上下改这里◀ */
    right: 16px;  /* ▶铅笔左右改这里◀ */
    background: transparent !important;
    z-index: 10;
}

.mesAvatarWrapper {
    position: relative;
    z-index: 5;
}

.mes_text #curEditTextarea {
    background-color: var(--myshadow2);
}

/* 头像 */
#chat .mes .mesAvatarWrapper {
    width: 0px !important;
    min-width: 0px !important;
    flex: 0 0 0px !important;
    margin: 0px !important;
    padding: 0px !important;
}

#chat .mesAvatarWrapper .avatar {
    position: absolute;
    top: -186px;  /* ▶头像上下改这里◀ */
    left: 12px;  /* ▶头像左右改这里◀ */
    width: 129px;
    height: 172px;
    background: white !important;
    transform: rotate(-5deg);
    border: 10px solid white;
    box-shadow: 0 1px 3px 0 rgba(var(--myshadow), 0.3);
    z-index: 5 !important;
}

#chat .mesAvatarWrapper .avatar img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover;
    position: absolute;
    top: 0;
    left: 0;
    box-shadow: none !important;
    border: 0 !important;
    border-radius: 0 !important;
}

/* 头像框粉色胶带 */
#chat .mesAvatarWrapper .avatar::after {
    content: "";
    position: absolute;
    top: 88px;  /* ▶胶带上下改这里◀ */
    left: 34px;  /* ▶胶带左右改这里◀ */
    width: 100%;
    height: 60%;  /* ▶胶带高度改这里◀ */
    background-image: url("https://i.postimg.cc/KzMGPTmh/firstava.png");
    background-size: 100% 100%;
    background-repeat: no-repeat;
    pointer-events: none;
    z-index: 10;
}

/* 楼层 */
#chat .mes .mesIDDisplay {
    position: absolute;
    top: -140px;  /* ▶楼层上下改这里◀ */
    left: 254px;  /* ▶楼层左右改这里◀ */
    color: var(--mycolor);
    opacity: 0.9;
    z-index: 10;
}

/* 计时器与字符器 */
#chat .tokenCounterDisplay,
#chat .mes_timer {
    position: absolute !important;
    left: 183px;  /* ▶计时和tokens左右改这里◀ */
    color: var(--mycolor);
    font-size: 0.75em !important;
    opacity: 0.6 !important;
    transform: rotate(-2deg);
    z-index: 10;
}
#chat .tokenCounterDisplay {
    top: -71px;  /* ▶tokens上下改这里◀ */
}
#chat .mes_timer {
    top: -92px;  /* ▶计时上下改这里◀ */
}

/* 删除消息 */
input[type='checkbox'].del_checkbox {
    background-color: var(--myred);
 }
 input[type='checkbox'].del_checkbox::before {
     background-color: white;
 }
 .del_checkbox {
     position: absolute !important;
     top: -34px;
     left: 13px;
     z-index: 10;
 }
 #chat .mes.selected {
     background-color: var(--myred) !important;
     border-radius: 0;
 }

/* 左右切换消息 */
.swipe_right, .swipe_left {
    opacity: 0.3 !important;
    color: var(--mycolor);
}
/* 右切换消息和计数器 */
.swipeRightBlock {
    right: 3px;
    bottom: 8px;
}
.swipes-counter {
    z-index: 10;
}
/* 左切换消息 */
.swipe_left {
    left: 17px;
    bottom: 25px;
}

/* 文本内容 */
.mes_text {
    text-align: left;
    line-height: 1.6;
    padding: 8px var(--mestextpadding) 10px;  /* ▶正文 上/左右/下 间距◀ */
}
.last_mes .mes_text {
    padding-bottom: 42px;  /* ▶如果发现最后一条消息在生成时底部有缝 改大这个 或者给min-height◀ */
}

/* 引用文本 */
.mes_text q {
    display: inline-block !important;
    vertical-align: middle; 
    box-sizing: border-box;
    max-width: 100%;  

    quotes: none; 

    background: url('https://i.postimg.cc/zGR1ZW0v/firsttext.png') repeat 18px 6px;
    background-size: 180px auto;
    border: 2px solid white;
    border-radius: 8px;
    box-shadow: 0 1px 3px 0 rgba(var(--myshadow), 0.2);

    padding: 0px 1px;
    margin-bottom: 1px;  /* ▶若对话上下遮挡改这个◀ */

    text-indent: 0;
}
.mes_text q::before,
.mes_text q::after {
    content: none !important;
}

/* 引用区块 */
.mes_text blockquote, 
.mes_reasoning blockquote {
    color: var(--SmartThemeQuoteColor);
    background-color: #fff;
    background-image: 
        linear-gradient(rgba(248, 187, 208, 0.18) 1px, transparent 1px),
        linear-gradient(90deg, rgba(248, 187, 208, 0.18) 1px, transparent 1px);
    background-size: 15px 15px;
    border-left-color:var(--myshadow2) ;
    padding: 10px;
    margin-bottom: 4px;
    box-shadow: 0 4px 6px rgba(var(--myshadow), 0.2);
}

.mes_ghost {
    position: absolute;
    top: -138px;  /* ▶隐藏楼层小幽灵上下◀ */
    right: 156px;  /* ▶隐藏楼层小幽灵左右◀ */
    font-size: 18px;
    z-index: 10;
}

/* 思维链 */
.mes_reasoning_details {
    margin-left: var(--mestextpadding);
    margin-right: var(--mestextpadding);
}
.mes_reasoning_header {
    position: relative;
    background-color: transparent;
    overflow: visible;
    margin: 0.2em 2px;
    padding: 20px;
    opacity: 1;
    z-index: 1;
}
.mes_reasoning_header_title{
    transform: rotate(-2deg);
}
.mes_reasoning_details:not([open]) .mes_reasoning_arrow {
    transform: translateY(-50%) rotate(172deg);
}
.mes_reasoning_details .mes_reasoning_arrow {
    top: 43%;
    right: 5px;
}
.mes_reasoning_header::before {
    content: "" ;
    position: absolute;
    top: -2px;  /* ▶蓝色便签上下改这里◀ */
    left: 3px;  /* ▶蓝色便签上下改这里◀ */
    width: 100%;
    height: 92%;
    background: url('https://i.postimg.cc/KY1GcJKh/firstbg2.png') no-repeat center !important;
    background-size: cover !important;
    transform: rotate(2deg);
    z-index: -1;
}
.mes_reasoning {
    border: none;
    border-radius: 12px;
    padding: 4px !important;
    background-color: var(--mydrawer);
    color: var(--SmartThemeBodyColor);
}
.mes_reasoning_actions {
    margin: 1.5em 0.8em 0.5em 0 !important;
}

.mes_block .reasoning_edit_textarea, .edit_textarea {
    margin-bottom: 6px;
    background-color: var(--myshadow2);
}

/* 文档模式 */
body.documentstyle #chat .mes {
    margin-top: 0 !important;
    padding-top: 70px !important;
    margin-bottom: 20px;
}
body.documentstyle #chat .mes::before {
    top: 18px;
}
body.documentstyle #chat .mes .mes_block {
    margin-right: 0;
}
body.documentstyle #chat .mes .mes_block::before {
    display: none;
}
body.documentstyle #chat .mes .mes_block .mes_buttons {
    top: -16px;
}
body.documentstyle #chat .mes .mes_text {
    margin-left: 0;
    padding: 0 20px 18px;
}
body.documentstyle #chat .mes input[type='checkbox'].del_checkbox {
    margin-top: 60px;
}
body.documentstyle #chat .smallSysMes {
    padding-top: 2px !important;
}

/* ===== 气泡结束 ===== */

/* ===== 底栏 ===== */

#form_sheld {
    position: absolute;
    bottom: 6px;
    padding: 0 6px;
}
#send_form {
    opacity: 1 !important;
    background: url('https://i.postimg.cc/QxPTcXPn/firstbg3.png') repeat center;
    background-size: 48%;
    border-radius: 16px;
    border: none;
    box-shadow: 0 2px 3px 1px rgba(var(--myshadow), 0.3);
}

#nonQRFormItems {
    position: relative;
    padding: 4px 0;
}

/* 输入框 */
#send_textarea {
    min-height: calc(var(--bottomFormBlockSize));
    border-top: none;
    clip-path: none;
    background-color: white;
    box-shadow: 0 1px 2px 1px rgba(var(--myshadow), 0.16);
    border-radius: 16px;
    margin: 2px 0;
}

/* 修改placeholder */
#send_textarea::placeholder {
    color: transparent !important;
}
#nonQRFormItems::before {
    content: "小狗疑心大宇宙阴谋篡夺他的位置...";
    position: absolute;
    left: 88px;  /* ▶输入框内置文字左右改这里◀ */
    right: 14px;
    top: 50%;
    transform: translateY(-50%);
    color: var(--mylight);
    pointer-events: none;
    font-size: 14px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
#nonQRFormItems:has(.mes_stop[style*="flex"])::before,
#nonQRFormItems:has(.mes_stop[style*="block"])::before {
    right: 98px;
}
#nonQRFormItems:has(#send_textarea:not(:placeholder-shown))::before {
    opacity: 0;
}

/* qrbar */
#qr--bar {
    display: none !important;
}
#send_form:focus-within #qr--bar {
    display: flex !important;
}
.qr--buttons {
    padding: 6px 3px 0 3px !important;
}
.qr--button {
    background-color: var(--mybutton) !important;
    border: 2px solid white !important;
    color: var(--SmartThemeQuoteColor) !important;
    font-size: 0.9em;
    margin: 2px !important;
}

/* 底栏图标 */
#leftSendForm, #rightSendForm {
    width: auto !important;
}

#rightSendForm>div, #leftSendForm>div {
    width: var(--bottomFormBlockSize);
    height: var(--bottomFormBlockSize);
}
#send_form .mes_stop {
    justify-content: center;
    align-items: center;
}
#send_but::before,
.fa-bars:before, .fa-navicon:before,
.fa-magic-wand-sparkles:before, .fa-wand-magic-sparkles:before,
.fa-circle-stop:before, .fa-stop-circle:before {
    opacity: 1 !important;
    font-size: 18px;  /* ▶底栏图标大小改这里◀ */
    color: var(--mylight);
    -webkit-text-stroke: 5px white;
    filter: drop-shadow(1px 1px 2px rgba(var(--myshadow), 0.4));
    paint-order: stroke fill; 
}
#rightSendForm>div:not(.mes_stop), #leftSendForm>div {
    opacity: 1;
}
#rightSendForm>div:hover, #leftSendForm>div:hover {
    filter: none;
}
/* 图标按下 */
#options, #extensionsMenu, .popup .popper-modal {
    background-color: var(--mybutton);
    box-shadow: 1px 1px 6px 2px rgba(var(--myshadow), 0.2);
    border: 2px solid white;
}
.options-content a, #extensionsMenu>.extension_container>div, #extensionsMenu>div:not(.extension_container), .list-group>div, .list-group .list-group-item, #sd_dropdown .list-group span {
    color: var(--mycolor);
    font-size: 0.9em;
}
.options-content, .list-group {
    border: none;
}
#extensionsMenu>.extension_container>div, #extensionsMenu>div:not(.extension_container), .options-content a, .list-group-item {
    opacity: 1 !important;
}
/* 管理聊天文件 */
#select_chat_popup {
    background-color: var(--mydrawer);
}
.select_chat_block[highlight] {
    background-color: var(--mylight);
    border: none;
}
.chatBackupsListItem {
    background-color: var(--mytextarea);
    border: none;
}

/* ===== 底栏结束 ===== */

/* ===== 顶栏 ===== */

#top-bar {
    box-shadow: none !important;
}
#top-settings-holder {
    background-color: var(--mydrawer);
}
.drawer-icon {
    opacity: .7 !important;  /* ▶顶栏图标透明度改这里◀ */
    font-size: 16px;  /* ▶顶栏图标大小改这里◀ */
    color: var(--mylight);
    -webkit-text-stroke: 6px white;
    filter: drop-shadow(1px 1px 2px rgba(var(--myshadow), 0.2));
    paint-order: stroke fill; 
}

/* ===== 顶栏结束 ===== */

/* ===== 顶栏抽屉展开 ===== */

/* ----- 预设 ----- */
.fillLeft .scrollableInner {
    padding-top: 1.5em;
}
#openai_api-presets .flexNoGap {
    margin: 6px 0;
}
#range_block_openai .inline-drawer .inline-drawer-header,
#advanced-ai-config-block #openai_settings .inline-drawer {
    margin: 8px 0;
}
#completion_prompt_manager .completion_prompt_manager_header {
    color: var(--mycolor);
}
#completion_prompt_manager .completion_prompt_manager_header_advanced span {
    filter: none;
    transition: none;
}
#completion_prompt_manager_popup {
    background-color: var(--mydrawer);
}
#completion_prompt_manager_list {
    position: relative;
    background-color: #fdfcfa;
    background-image: 
        linear-gradient(to right, var(--mydrawer) 1px, transparent 1px),
        linear-gradient(to bottom, var(--mydrawer) 1px, transparent 1px);
    background-size: 20px 20px;
    border-radius: 5px 20px 20px 5px;
    box-shadow: 1px 1px 4px 2px rgba(var(--myshadow), 0.08);
    padding: 0 12px 50px 12px;
}
#completion_prompt_manager_list::before {
    content: 'Sweet Whispers';
    position: absolute;
    bottom: 12px;
    left: 50%;
    transform: translateX(-50%);
    font-size: 0.85em;
    font-style: italic;
    color: rgba(var(--myshadow), 0.24);
    padding-bottom: 10px;
    border-bottom: 1px solid rgba(var(--myshadow), 0.3);
}

#completion_prompt_manager_list li.completion_prompt_manager_prompt span span span {
    opacity: 1 !important;
    filter: none !important;
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_name .prompt-manager-inspect-action:focus-visible,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_name .prompt-manager-inspect-action:hover {
    text-decoration: none !important;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
    background: url('https://i.postimg.cc/zGR1ZW0v/firsttext.png') repeat center;
    background-size: 60%;
    border: none !important;
    border-radius: 0;
    margin-bottom: 8px;
    padding: 6px 10px;
    box-shadow: 1px 2px 4px 1px rgba(var(--myshadow), 0.14);
    color: var(--mycolor) !important; /* 这里控制 Token 词符数颜色 */
}
#completion_prompt_manager_list li.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt-manager-inspect-action {
    color: var(--mycolor) !important;
    font-weight: 500;
}

/* 预设右侧按钮 */
#completion_prompt_manager_list li.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .fa-asterisk,
#completion_prompt_manager_list li.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt-manager-edit-action,
#completion_prompt_manager_list li.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt-manager-toggle-action {
    color: var(--mycolor) !important;
}
#completion_prompt_manager_list li.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .drag-handle {
    color: var(--mycolor) !important;
    opacity: 0.8;
}
#completion_prompt_manager_list li.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt-manager-detach-action {
    color: var(--myred) !important;
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .completion_prompt_manager_prompt_name .fa-solid {
    color: var(--mytextarea);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
    opacity: 0.6;
    filter: grayscale(0.8);
    box-shadow: none !important; /* 禁用时去掉阴影更平整 */
    color: var(--mygrey) !important;   /* 禁用时 Token 词符数变灰 */
}
#completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled .prompt-manager-inspect-action {
    color: var(--mygrey) !important; /* 名字变灰 */
}
#completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled .drag-handle,
#completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled .fa-asterisk,
#completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled .prompt-manager-edit-action,
#completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled .prompt-manager-detach-action,
