/* 去除某些高亮 */
a:focus-visible {
    filter: none !important;
}

.custom-drawer-icon, 
.inline-drawer-icon {
    filter: none;
}
/* 展开/合上按钮 */
.fa-chevron-circle-down:before,
.fa-circle-chevron-down:before,
.fa-chevron-circle-up:before, 
.fa-circle-chevron-up:before {
    color: var(--mylight);
    -webkit-text-stroke: 6px white;
    filter: drop-shadow(2px 2px 4px rgba(var(--myshadow), 0.4));
    paint-order: stroke fill; 
}

/* ----- button开始 ----- */
.menu_button {
    background-color: var(--mybutton);
    color: var(--mycolor);
    box-shadow: 1px 1px 2px 1px rgba(var(--myshadow), 0.2);
    border: 1px solid rgba(255, 255, 255, 0.4);
    border-radius: 6px;
    filter: none;
    transition: background-color 0.15s ease;
    outline: none;
}
.menu_button.menu_button_default, 
.menu_button.popup-button-ok,
#dialogue_del_mes_ok {
    background-color: var(--myblack);
    color: var(--mycolor);
    border: none !important;
}
.red_button, .redWarningBG {
    background-color: var(--mybutton) !important;
    color: var(--myred);
}
.menu_button[disabled], .menu_button.disabled {
    filter: none;
    background-color: var(--mytextarea);
}

/* 弹框btn控制 */
.popup-controls {
    display: flex;
    flex-direction: row;
    flex-wrap: nowrap;
    justify-content: center;
    align-items: center;
    gap: 8px;
    width: 100%;
    overflow: visible;
    margin-top: 2px;
    padding: 8px 2px;
}
.popup-controls .menu_button,
.vfm__content .menu_button{
    white-space: nowrap;
    flex: 1 1 0;
    max-width: 120px;
    font-size: 13px;
    padding: 6px 12px;
    box-sizing: border-box;
}

/* 删除消息btn控制 */
#dialogue_del_mes .menu_button {
    margin-left: 12px;
    margin-right: 12px;
    padding: 3px 24px;
}
/* mes铅笔下btn */
.mes_edit_buttons {
    filter: none !important;
    padding-right: var(--mestextpadding);
}
.mes_reasoning_edit_done, 
.mes_edit_done.menu_button {
    background-color: var(--mylight);
}
.mes_reasoning_edit_cancel, 
.mes_edit_cancel.menu_button {
    background-color: var(--myblack);
}
/* 思维链铅笔btn */
.mes_reasoning_actions .edit_button {
    filter: none;
}
.mes_reasoning_actions {
    padding-right: var(--mestextpadding);
}

/* 优化双端button */
.menu_button:not(.disabled):not([disabled]):active {
    background-color: var(--myhit) !important;
    transition: none !important;
}

@media (hover: hover) {
    .menu_button:not(.disabled):not([disabled]):hover:not(:active) {
        background-color: var(--myhit);
        cursor: pointer;
    }

    .menu_button.menu_button_default:hover:not(:active),
    .menu_button.popup-button-ok:hover:not(:active) {
        background-color: var(--myhit) !important;
    }
}

@media (hover: none) {
    .menu_button:focus, 
    .menu_button:hover {
        background-color: var(--mybutton) !important; 
        color: var(--mycolor) !important;
    }

    .menu_button.menu_button_default:focus,
    .menu_button.menu_button_default:hover,
    .menu_button.popup-button-ok:focus {
        background-color: var(--myblack) !important;
        color: var(--mycolor) !important;
    }
}

.menu_button, 
.menu_button:focus, 
.menu_button:active, 
.menu_button:focus-visible,
.menu_button_default,
.menu_button_default:focus {
    outline: none !important;
}

.menu_button.active:not(:active) {
    background-color: inherit;
}

a:hover {
    filter: none;
}
/* ----- button结束 ----- */

/* 文本框 */
input,
.text_pole,
textarea,
.reasoning_edit_textarea, 
.edit_textarea {
    background-color: var(--mytextarea);
    border-radius: 8px;
    border: none;
}
input::placeholder,
.text_pole::placeholder,
textarea::placeholder {
    color: rgba(var(--myshadow), 0.6) !important;
}
/* 常见最大化文字区域背景颜色 css填入/user描述/char描述/世界书 */
textarea.maximized_textarea[data-for="customCSS"],
textarea.maximized_textarea[data-for="persona_description"],
textarea.maximized_textarea[data-for="description_textarea"],
textarea.maximized_textarea[data-for="firstmessage_textarea"],
textarea.maximized_textarea[data-for^="world_entry_content_"]  {
    background-color: var(--myshadow2) !important;
}

/* select框 */
select {
    background-color: var(--mytextarea);
    outline: none;
    border-radius: 8px;
    border: none;
    scrollbar-width: none;
    -ms-overflow-style: none;
}
select option {
    background-color: var(--mytextarea) !important;
    color: var(--SmartThemeBodyColor) !important;
}
select:active {
    background-color: var(--mytextarea);
    transition: none;
}
select::-webkit-scrollbar {
    display: none !important;
    width: 0 !important;
}

/* 提示框 */
.toast-top-center {
    top: 12px;
}
#toast-container>div {
    background-color: var(--myblack) !important;
    color: var(--mycolor) !important;
    border-radius: 10px;
    border: none;
    -webkit-box-shadow:0 2px 6px 1px rgba(var(--myshadow), 0.4);
    box-shadow:0 2px 6px 1px rgba(var(--myshadow), 0.4);
    padding: 14px 10px 14px 50px !important;
}
#toast-container>div:hover {
    -webkit-box-shadow:0 2px 6px 1px rgba(var(--myshadow), 0.4);
    box-shadow:0 2px 6px 1px rgba(var(--myshadow), 0.4);
}

#toast-container>.toast-success,
#toast-container>.toast-error,
#toast-container>.toast-info,
#toast-container>.toast-warning {
    background-image: none !important; 
}
#toast-container > .toast-success::before,
#toast-container > .toast-error::before,
#toast-container > .toast-info::before,
#toast-container > .toast-warning::before {
    font-family: "Font Awesome 6 Free"; 
    font-weight: 900;
    position: absolute;
    left: 15px;
    top: 50%;
    transform: translateY(-50%);
    font-size: 22px;
    color: var(--mylight);
}
#toast-container > .toast-success::before {
    content: "\f6d3"; 
}
#toast-container > .toast-error::before {
    content: "\f086"; 
}
#toast-container > .toast-info::before {
    content: "\f6be"; 
}
#toast-container > .toast-warning::before {
    content: "\f071"; 
}

/* 弹出框 */
.popup {
    background-color: var(--myshadow2);
    box-shadow: 0 2px 6px 2px rgba(var(--myshadow), 0.4);
    padding: 4px 8px;
}

/* 勾选框 */
.checkbox_label {
    align-items: center !important;
}
input[type='checkbox'] {
    outline: none;
    background-color: var(--mytextarea);
    width: calc(var(--mainFontSize) + 5px) !important;
    height: calc(var(--mainFontSize) + 5px) !important;
    border: none;
    filter: none;
}
input[type="checkbox"]::before {
    box-shadow: none !important; 
    background-color: var(--SmartThemeQuoteColor);
}

/* 范围块 */
input[type="range"] {
    background: rgba(var(--myshadow), 0.16) !important;
    border-radius: 8px !important;
    box-shadow: none;
    filter: none;
}
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 20px;
    height: 20px;
    background-color: white;
    border-radius: 50%;
    cursor: pointer;
    border: none;
    box-shadow: 0 2px 6px rgba(var(--myshadow),0.4);
}
.range-block-counter input {
    background-color: var(--mytextarea);
    border: none;
    border-radius: 8px;
}
input[type="range"],
.neo-range-slider:hover, 
input[type="range"]:hover {
    filter: none !important;
}
.neo-range-slider:focus-visible, 
input[type="range"]:focus-visible {
    outline: none !important;
}
.neo-range-slider {
    box-shadow: none !important;
}
.neo-range-input {
    background-color: var(--mybutton);
    box-shadow: 1px 1px 4px 1px rgba(var(--myshadow), 0.16);
    border: 1px solid rgba(255, 255, 255, 0.4);
}

/* ----- 抽屉内样式开始 ----- */
.drawer-content {
    border: 0 !important;
    background-color: var(--mydrawer);
    box-shadow: 1px 3px 6px 1px rgba(var(--myshadow), 0.3) !important;
    transform: translateZ(0);
}

.drawer-content h4,
.standoutHeader,
.inline-drawer-header {
    border: 3px solid white !important;
    border-radius: 10px !important;
    box-shadow: 0 2px 4px 1px rgba(var(--myshadow), 0.2) !important;
    padding: 2px 5px !important;
}

.drawer-content h4,
.standoutHeader {
    background: url('https://i.postimg.cc/xjhk9rFS/firstbg1.png') repeat center !important;
    background-size: 200px !important;
    background-attachment: fixed !important;
}

.inline-drawer-header {
    background-color: white !important;
    background-image: 
        radial-gradient(color-mix(in srgb, var(--myred), transparent 80%) 10%, transparent 10%), 
        radial-gradient(color-mix(in srgb, var(--myred), transparent 80%) 10%, transparent 10%) !important;
    background-position: 0 -6px, 10px 4px !important;
    background-size: 20px 20px !important;
}

/* 优化抽屉 */
@media (hover: hover) {
    .inline-drawer-toggle.inline-drawer-header:hover, 
    .standoutHeader.inline-drawer-header:hover {
        filter: none !important;
        background-color: transparent;
    }
}
.inline-drawer-header,
.standoutHeader.inline-drawer-header,
.inline-drawer-header:focus,
.inline-drawer-header:focus-visible {
    filter: none !important;
    outline: none !important;
    -webkit-tap-highlight-color: transparent !important;
}

/* ----- 抽屉内样式结束 ----- */

/* 分割线 */
#options .options-content hr {
    display: none;
}
hr {
    border: none;
    height: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    margin: 8px 0;
    background: 
        linear-gradient(to right, transparent, var(--myred)) no-repeat left center / calc(50% - 15px) 1px,
        linear-gradient(to left, transparent, var(--myred)) no-repeat right center / calc(50% - 15px) 1px;
}
hr::before {
    content: "\f004";
    font-family: "Font Awesome 6 Free";
    font-weight: 900;  
    font-size: 14px;
    color: var(--myred);
    display: flex;
    align-items: center;
    justify-content: center;
}

.mes_text hr {
    background: url('https://i.postimg.cc/x1hJTw1W/firsthr.png') no-repeat center !important;
    background-size: 100% !important;
    height: 32px;
    opacity: 1 !important;
    margin: 0 auto !important;
}
.mes_text hr::before {
    display: none !important;
}

/* input's radio */
input[type="radio"] {
    accent-color: var(--mycolor);
}

/* code */
.mes_text pre code, 
.mes_reasoning pre code,
code {
    background-color: rgb(244, 243, 244);
    color: var(--mycolor);
    border: 2px solid white;
    border-radius: 0;
    box-shadow: 1px 1px 2px 1px rgba(var(--myshadow), 0.2);

    box-decoration-break: clone;
    -webkit-box-decoration-break: clone;
}

/* 左边框提示条 高级格式化设置+正则+user卡 */
.info-block.warning,
.info-block.info,
.info-block.hint  {
    background-color: var(--mytextarea);
    border-color:var(--mytextarea);
}

/* 处理br */
.mes_text hr + br {
    display: none !important;
}

/* ===== 公共样式结束 ===== */

/* ===== 加载页 ===== */

.popup:has(#loader) {
    width: 100vw !important;
    height: 100vh !important;
    max-width: 100vw !important;
    max-height: 100vh !important;
    top: 0;
    left: 0;
    border-radius: 0;
}
.popup:has(#loader) .popup-body {
    height: 100% !important;
    display: flex;
    align-items: center;
    justify-content: center;
}

#load-spinner {
    all: unset;
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 80px;
    height: 80px;
    display: block;
}
#load-spinner::before {
    content: "";
    display: block;
    width: 100%;
    height: 100%;
    background-image: url('https://i.postimg.cc/hvfLzcjQ/firstloading.png');
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    animation: bear-float-new 2s ease-in-out infinite alternate;
}
#load-spinner::after {
    content: "";
    position: absolute;
    bottom: -20px;
    left: 50%;
    width: 60px;
    height: 10px;
    margin-left: -30px;
    background: rgba(0, 0, 0, 0.1);
    border-radius: 50%;
    animation: shadow-scale-new 2s ease-in-out infinite alternate;
}
#loader::after {
    content: "小熊正在努力加载中...";
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, 80px);
    color: var(--mycolor);
    font-size: 14px;
    font-weight: bold;
    white-space: nowrap;
}
@keyframes bear-float-new {
    from { transform: translateY(5px) rotate(-2deg); }
    to { transform: translateY(-15px) rotate(2deg); }
}
@keyframes shadow-scale-new {
    from { transform: scale(1.2); opacity: 0.3; }
    to { transform: scale(0.8); opacity: 0.1; }
}

/* ===== 加载页结束 ===== */

